function FloydWarshallClosure(c):
    d <- copy(c)
    for k = 0 to n-1:
        for i = 0 to n-1:
            for j = 0 to n-1:
                d[i,j] <- min(d[i,j], d[i,k] + d[k,j])
    feasible <- all(d[i,i] >= 0)
    return (d, feasible)

Complexity: O(n^3) time, O(n^2) space

function BellmanFord(n, E):
    dist <- array of n zeros
    for iteration = 1 to n-1:
        for (i, j, w) in E:
            if dist[j] + w < dist[i]:
                dist[i] <- dist[j] + w
    for (i, j, w) in E:
        if dist[j] + w < dist[i]:
            return (infeasible, negative cycle)
    return (feasible, dist)

Complexity: O(n * |E|) time, O(n) space
